/// <summary>
///    Finds the specified record in the <c>KCS_DirProductGroup</c> table.
/// </summary>
/// <param name="_recordId">
///    The record ID of the <c>KCS_DirProductGroup</c> record to find.
/// </param>
/// <param name="_forUpdate">
///    A Boolean value that indicates whether to read the record for update; optional.
/// </param>
/// <returns>
///    A record in the <c>KCS_DirProductGroup</c> table; otherwise, an empty record.
/// </returns>
public static KCS_DirProductGroup find( KCS_DirProductGroupID   _recordId,
                                        boolean                 _forUpdate = false)
{
    KCS_DirProductGroup record;

    if (_recordId)
    {
        record.selectForUpdate(_forUpdate);

        select firstonly record
        index hint KCS_DirProductGroupIDIdx
        where   record.KCS_DirProductGroupID == _recordId;
    }

    return record;
}

/// <summary>
/// Finds the specified record in the <c>KCS_DirProductGroup</c> table by RecId.
/// </summary>
/// <param name="_recId">
///    The record ID of the <c>KCS_DirProductGroup</c> record to find.
/// </param>
/// <param name="_forUpdate">
///    A Boolean value that indicates whether to read the record for update; optional.
/// </param>
/// <returns>
///    A record in the <c>KCS_DirProductGroup</c> table; otherwise, an empty record.
/// </returns>
public static KCS_DirProductGroup findByRecId(RecId _recId, boolean _forUpdate = false)
{
    KCS_DirProductGroup record;

    if (_recId)
    {
        record.selectForUpdate(_forUpdate);

        select firstonly record
            index hint KCS_DirProductGroupIDIdx
            where record.RecId == _recId;
    }

    return record;
}

/// <summary>
///    AVA <c>editAddressSelection</c> method.
/// </summary>
/// <param name="_set">
///    <c>boolean</c> as type
/// </param>
/// <param name="_competitorPartyId">
///    <c>DirPartyRecId</c> as type
/// </param>
/// <param name="_mapProdGrpAddrRanking">
///    <c>Map</c> as type
/// </param>
/// <param name="_productGrpAddressRanking">
///    <c>KCS_DirProductGrpAddressRanking</c> as type
/// </param>
/// <param name="_productGroupId">
///    <c>KCS_DirProductGroupId</c> as type
/// </param>
/// <param name="_common">
///    <c>Common</c> as type
/// </param>
/// <returns>
///    <c>DirPartyRecId</c> as return value
/// </returns>
public DirPartyRecId editAddressSelection(  boolean                         _set,
                                            DirPartyRecId                   _competitorPartyId,
                                            Map                             _mapProdGrpAddrRanking,
                                            KCS_DirProductGrpAddressRanking _productGrpAddressRanking,
                                            KCS_DirProductGroupId           _productGroupId,
                                            Common                          _common
                                            )
{
    DirPartyRecId   locCompetitorPartyId;

    Map             locMapProdGrpAddrRanking;

    locMapProdGrpAddrRanking = _mapProdGrpAddrRanking;

    if (locMapProdGrpAddrRanking == null)
    {
        locMapProdGrpAddrRanking = new Map(Types::String, Types::Container);
    }

    if (_set)
    {
        if (_competitorPartyId)
        {
            if (!SmmQuotationCompetitorGroup::find(_competitorPartyId))
            {
                error(strfmt("@NDX:NXASelectedCompetitorDoesNotExist", _competitorPartyId, tableid2pname(tablenum(SmmQuotationCompetitorGroup))));
                return 0;
            }
            if (!locMapProdGrpAddrRanking.exists(_productGroupId))
            {
                locMapProdGrpAddrRanking.insert(_productGroupId,
                                                KCS_DirProductGroupAddressRanking::addMapValueCompPartyId(  connull(),
                                                                                                            _productGrpAddressRanking, 
                                                                                                            _competitorPartyId  )
                                                );
            }
            else
            {
                locMapProdGrpAddrRanking.insert(_productGroupId,
                                                KCS_DirProductGroupAddressRanking::addMapValueCompPartyId(  locMapProdGrpAddrRanking.lookup(_productGroupId),
                                                                                                            _productGrpAddressRanking, 
                                                                                                            _competitorPartyId));
            }
            locCompetitorPartyId = _competitorPartyId;
        }
        else
        {
            if (locMapProdGrpAddrRanking.exists(_productGroupId))
            {
                locMapProdGrpAddrRanking.insert(_productGroupId, KCS_DirProductGroupAddressRanking::addMapValueCompPartyId(locMapProdGrpAddrRanking.lookup(_productGroupId), _productGrpAddressRanking, 0));
                KCS_DirProductGroupAddressRanking::deleteByCustPartyProdGroup(_common, _productGroupId, _productGrpAddressRanking);
            }
        }
    }
    else
    {
        if (locMapProdGrpAddrRanking.exists(_productGroupId))
        {
            locCompetitorPartyId = KCS_DirProductGroupAddressRanking::findValueCompetionPartyId(locMapProdGrpAddrRanking.lookup(_productGroupId), _productGrpAddressRanking);
        }
    }

    //return DirPartyTable::findRec(locCompetitorPartyId).Name;
    return locCompetitorPartyId;
}

/// <summary>
///    AVA <c>competitorNameForBVBuildProject</c> method.
/// </summary>
/// <param name="_common">
///    <c>Common</c> as type
/// </param>
/// <param name="_productGroupId">
///    <c>KCS_DirProductGroupID</c> as type
/// </param>
/// <param name="_addressRanking">
///    <c>KCS_DirProductGrpAddressRanking</c> as type
/// </param>
/// <returns>
///    <c>Name</c> as return value
/// </returns>
public Name competitorNameForRanking(   Common                          _common,
                                        KCS_DirProductGroupID           _productGroupId,
                                        KCS_DirProductGrpAddressRanking _addressRanking
                                        )
{
    KCS_DirProductGroupAddressRanking   productGroupAddressRanking;

    select firstonly  productGroupAddressRanking
        where   productGroupAddressRanking.RefTableId               == _common.TableId
            &&  productGroupAddressRanking.RefRecId                 == _common.RecId
            &&  productGroupAddressRanking.ProductGrpAddressRanking == _addressRanking
            &&  productGroupAddressRanking.ProductGroupId           == _productGroupId;

    return DirPartyTable::findRec(productGroupAddressRanking.DirPartyId).Name;

}

/// <summary>
///    AVA <c>editPartyCompetitorCommon</c> method.
/// </summary>
/// <param name="_set">
///    <c>boolean</c> as type
/// </param>
/// <param name="_dirPartyRecId">
///    <c>DirPartyRecId</c> as type
/// </param>
/// <param name="_addressRanking">
///    <c>KCS_DirProductGrpAddressRanking</c> as type
/// </param>
/// <param name="_productGroupId">
///    <c>KCS_DirProductGroupId</c> as type
/// </param>
/// <param name="_common">
///    <c>Common</c> as type
/// </param>
/// <returns>
///    <c>Name</c> as return value
/// </returns>
public Name editPartyCompetitor(boolean                         _set,
                                DirPartyRecId                   _dirPartyRecId,
                                KCS_DirProductGrpAddressRanking _addressRanking,
                                KCS_DirProductGroupId           _productGroupId,
                                Common                          _common
                                )
{
    Name        competitorName;

    if (!_set)
    {
        competitorName  = this.competitorNameForRanking(_common,
                                                        _productGroupId,
                                                        _addressRanking);
    }
    else
    {
        this.createOrUpdateProductGroupAddressRanking(  _common,
                                                        _productGroupId,
                                                        _addressRanking,
                                                        _dirPartyRecId);
    }

    return competitorName;
}

/// <summary>
///    AVA <c>createOrUpdateProductGroupAddressRanking</c> method.
/// </summary>
/// <param name="_common">
///    <c>Common</c> as type
/// </param>
/// <param name="_productGroupId">
///    <c>KCS_DirProductGroupID</c> as type
/// </param>
/// <param name="_ranking">
///    <c>KCS_DirProductGrpAddressRanking</c> as type
/// </param>
/// <param name="_compPartyId">
///    <c>DirPartyRecId</c> as type
/// </param>
public void createOrUpdateProductGroupAddressRanking(   Common                          _common,
                                                        KCS_DirProductGroupID           _productGroupId,
                                                        KCS_DirProductGrpAddressRanking _ranking,
                                                        DirPartyRecId                   _compPartyId
                                                        )
{
    KCS_DirProductGroupAddressRanking   findRanking;

    KCS_KBVBuildingProjectTable         locKCS_KBVBuildingProjectTable;
    smmBusRelTable                      locsmmBusRelTable;
    CustTable                           locCustTable;
    DirPartyTable                       locDirPArtyTable;
    KCS_DirProdGroupAddressType         locKCS_DirProdGroupAddressType;

    locKCS_DirProdGroupAddressType  = KCS_DirProdGroupAddressType::DirParty;

    switch(_common.TableId)
    {
        case tableNum(KCS_KBVBuildingProjectTable):
            locKCS_KBVBuildingProjectTable  = _common;
            locKCS_DirProdGroupAddressType  = KCS_DirProdGroupAddressType::KBVBuildingProject;
            break;

        case tableNum(smmBusRelTable):
            locsmmBusRelTable               = _common;
            break;

        case tableNum(CustTable):
            locCustTable                    = _common;
            break;

        case tableNum(DirPartyTable):
            locDirPArtyTable                = _common;
            break;

    }

    findRanking = KCS_DirProductGroupAddressRanking::findCommon(_productGroupId,
                                                                _common,
                                                                _ranking,
                                                                true
                                                                );

    ttsbegin;

    if (findRanking.RecId)
    {
        if (    _compPartyId            == 0
            ||  findRanking.DirPartyId  != _compPartyId)
        {
            if(_compPartyId)
            {
                findRanking.DirPartyId = _compPartyId;
                findRanking.update();
            }
            else
            {
                findRanking.delete();
            }
        }
    }
    else
    {
        if(_compPartyId)
        {
            findRanking.clear();
            findRanking.initValue();
            findRanking.ProductGroupId              = _productGroupId;
            findRanking.DirPartyId                  = _compPartyId;
            findRanking.ProductGrpAddressRanking    = _ranking;
            findRanking.RefTableId                  = _common.TableId;
            findRanking.RefRecId                    = _common.RecId;
            findRanking.KCS_KBVBuildingProjectID    = locKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID;
            findRanking.BusRelAccount               = locsmmBusRelTable.BusRelAccount;
            findRanking.CustAccount                 = locCustTable.AccountNum;
            findRanking.PartyNumber                 = locDirPArtyTable.PartyNumber;
            findRanking.DirProdGroupAddressType     = locKCS_DirProdGroupAddressType;
            findRanking.insert();
        }
    }

    ttscommit;
}

/// <summary>
/// Dipslay Product group description
